using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using RauchERP.Application.Abstractions;
using RauchERP.Modules.Catalog.Application;
using RauchERP.Modules.Catalog.Contracts;
using RauchERP.Modules.Catalog.Domain;
using RauchERP.SharedKernel;

namespace RauchERP.Modules.Catalog.Infrastructure;

public sealed class CatalogDbContext(DbContextOptions<CatalogDbContext> options) : DbContext(options)
{
    public DbSet<Category> Categories => Set<Category>(); public DbSet<Brand> Brands => Set<Brand>(); public DbSet<Product> Products => Set<Product>(); public DbSet<ProductVariant> ProductVariants => Set<ProductVariant>(); public DbSet<AttributeDefinition> AttributeDefinitions => Set<AttributeDefinition>(); public DbSet<AttributeValue> AttributeValues => Set<AttributeValue>(); public DbSet<ProductVariantAttribute> ProductVariantAttributes => Set<ProductVariantAttribute>(); public DbSet<ProductImage> ProductImages => Set<ProductImage>(); public DbSet<PriceList> PriceLists => Set<PriceList>(); public DbSet<ProductPrice> ProductPrices => Set<ProductPrice>();
    protected override void OnModelCreating(ModelBuilder b)
    {
        b.HasDefaultSchema("catalog");
        b.Entity<Category>(x => { x.ToTable("categories"); x.HasKey(e => e.Id); x.Property(e => e.Name).HasMaxLength(160); x.Property(e => e.Description).HasMaxLength(1000); x.HasIndex(e => new { e.CompanyId, e.ParentCategoryId, e.Name }).IsUnique(); });
        b.Entity<Brand>(x => { x.ToTable("brands"); x.HasKey(e => e.Id); x.Property(e => e.Name).HasMaxLength(160); x.HasIndex(e => new { e.CompanyId, e.Name }).IsUnique(); });
        b.Entity<Product>(x => { x.ToTable("products"); x.HasKey(e => e.Id); x.Property(e => e.Name).HasMaxLength(200); x.Property(e => e.Description).HasMaxLength(2000); x.Property(e => e.ProductType).HasMaxLength(50); x.HasMany(e => e.Variants).WithOne().HasForeignKey(e => e.ProductId); });
        b.Entity<ProductVariant>(x => { x.ToTable("product_variants"); x.HasKey(e => e.Id); x.Property(e => e.Sku).HasMaxLength(80); x.Property(e => e.Barcode).HasMaxLength(80); x.Property(e => e.Name).HasMaxLength(200); x.Property(e => e.UnitOfMeasure).HasMaxLength(40).HasDefaultValue("Unidad"); x.Property(e => e.Cost).HasPrecision(19, 4); x.Property(e => e.BasePrice).HasPrecision(19, 4); x.Property(e => e.TaxRate).HasPrecision(7, 4); x.HasIndex(e => new { e.CompanyId, e.Sku }).IsUnique(); x.HasIndex(e => new { e.CompanyId, e.Barcode }).IsUnique().HasFilter("\"Barcode\" IS NOT NULL"); x.Ignore(e => e.Attributes); });
        b.Entity<AttributeDefinition>(x => { x.ToTable("attribute_definitions"); x.HasKey(e => e.Id); x.Property(e => e.Name).HasMaxLength(100); x.HasIndex(e => new { e.CompanyId, e.Name }).IsUnique(); });
        b.Entity<AttributeValue>(x => { x.ToTable("attribute_values"); x.HasKey(e => e.Id); x.Property(e => e.Value).HasMaxLength(120); x.HasIndex(e => new { e.AttributeDefinitionId, e.Value }).IsUnique(); });
        b.Entity<ProductVariantAttribute>(x => { x.ToTable("product_variant_attributes"); x.HasKey(e => new { e.ProductVariantId, e.AttributeValueId }); });
        b.Entity<ProductImage>(x => { x.ToTable("product_images"); x.HasKey(e => e.Id); x.Property(e => e.Url).HasMaxLength(1000); });
        b.Entity<PriceList>(x => { x.ToTable("price_lists"); x.HasKey(e => e.Id); x.Property(e => e.Name).HasMaxLength(120); });
        b.Entity<ProductPrice>(x => { x.ToTable("product_prices"); x.HasKey(e => e.Id); x.Property(e => e.Price).HasPrecision(19, 4); x.HasIndex(e => new { e.PriceListId, e.ProductVariantId }).IsUnique(); });
    }
}

internal sealed class CatalogService(CatalogDbContext db, ICompanyContext context, IHostEnvironment environment) : ICatalogService, IProductVariantPricing
{
    private static DateTimeOffset Now => DateTimeOffset.UtcNow;
    public async Task<Result<CategoryResponse>> CreateCategoryAsync(CreateCategoryRequest r, CancellationToken ct) { if (!Allowed(r.CompanyId)) return Denied<CategoryResponse>(); if (await db.Categories.AnyAsync(x => x.CompanyId == r.CompanyId && x.ParentCategoryId == r.ParentCategoryId && x.Name.ToLower() == r.Name.Trim().ToLower(), ct)) return Result<CategoryResponse>.Failure(new("catalog.category_conflict", "Category name already exists at this level.")); var result = Category.Create(r.CompanyId, r.Name, r.Description, r.ParentCategoryId, Now); if (result.IsFailure) return Result<CategoryResponse>.Failure(result.Error); var x = result.Value!; db.Categories.Add(x); await db.SaveChangesAsync(ct); return Result<CategoryResponse>.Success(new(x.Id, x.CompanyId, x.Name, x.Description, x.ParentCategoryId, x.IsActive)); }
    public async Task<IReadOnlyList<CategoryResponse>> GetCategoriesAsync(Guid companyId, CancellationToken ct) => Allowed(companyId) ? await db.Categories.AsNoTracking().Where(x => x.CompanyId == companyId).OrderBy(x => x.Name).Select(x => new CategoryResponse(x.Id, x.CompanyId, x.Name, x.Description, x.ParentCategoryId, x.IsActive)).ToListAsync(ct) : [];
    public async Task<Result<BrandResponse>> CreateBrandAsync(CreateBrandRequest r, CancellationToken ct) { if (!Allowed(r.CompanyId)) return Denied<BrandResponse>(); if (string.IsNullOrWhiteSpace(r.Name)) return Result<BrandResponse>.Failure(new("catalog.brand_name_required", "Brand name is required.")); if (await db.Brands.AnyAsync(x => x.CompanyId == r.CompanyId && x.Name.ToLower() == r.Name.Trim().ToLower(), ct)) return Result<BrandResponse>.Failure(new("catalog.brand_conflict", "Brand already exists.")); var x = new Brand(r.CompanyId, r.Name, r.Description); db.Brands.Add(x); await db.SaveChangesAsync(ct); return Result<BrandResponse>.Success(new(x.Id, x.CompanyId, x.Name, x.IsActive)); }
    public async Task<IReadOnlyList<BrandResponse>> GetBrandsAsync(Guid companyId, CancellationToken ct) => Allowed(companyId) ? await db.Brands.AsNoTracking().Where(x => x.CompanyId == companyId).OrderBy(x => x.Name).Select(x => new BrandResponse(x.Id, x.CompanyId, x.Name, x.IsActive)).ToListAsync(ct) : [];
    public async Task<Result<ProductResponse>> CreateProductAsync(CreateProductRequest r, CancellationToken ct)
    {
        if (!Allowed(r.CompanyId)) return Denied<ProductResponse>(); if (!await db.Categories.AnyAsync(x => x.Id == r.CategoryId && x.CompanyId == r.CompanyId && x.IsActive, ct)) return Result<ProductResponse>.Failure(new("catalog.category_invalid", "Category is invalid."));
        var requestedSkus = r.Variants.Select(x => x.Sku.Trim().ToUpperInvariant()).ToList(); if (requestedSkus.Distinct().Count() != requestedSkus.Count || await db.ProductVariants.AnyAsync(x => x.CompanyId == r.CompanyId && requestedSkus.Contains(x.Sku), ct)) return Result<ProductResponse>.Failure(new("catalog.sku_conflict", "SKU must be unique per company."));
        var variants = new List<ProductVariant>(); foreach (var v in r.Variants) { var created = ProductVariant.Create(r.CompanyId, v.Sku, v.Barcode, v.Name, v.UnitOfMeasure, v.Cost, v.BasePrice, v.TaxRate, Now); if (created.IsFailure) return Result<ProductResponse>.Failure(created.Error); variants.Add(created.Value!); }
        var productResult = Product.Create(r.CompanyId, r.CategoryId, r.BrandId, r.Name, r.Description, r.ProductType, r.TracksInventory, variants, Now); if (productResult.IsFailure) return Result<ProductResponse>.Failure(productResult.Error); var product = productResult.Value!; db.Products.Add(product); await db.SaveChangesAsync(ct);
        for (var i = 0; i < variants.Count; i++) await SaveAttributes(variants[i].Id, r.CompanyId, r.Variants.ElementAt(i).Attributes, ct); await db.SaveChangesAsync(ct); return Result<ProductResponse>.Success(Map(product, []));
    }
    public async Task<ProductResponse?> GetProductAsync(Guid id, CancellationToken ct) { var x = await db.Products.AsNoTracking().Include(p => p.Variants).SingleOrDefaultAsync(p => p.Id == id && p.CompanyId == context.CompanyId, ct); if (x is null) return null; var images = await db.ProductImages.AsNoTracking().Where(i => i.ProductId == id).OrderBy(i => i.SortOrder).Select(i => i.Url).ToListAsync(ct); return Map(x, images); }
    public async Task<IReadOnlyList<ProductResponse>> SearchProductsAsync(ProductSearch s, CancellationToken ct) { if (!Allowed(s.CompanyId)) return []; var q = db.Products.AsNoTracking().Include(x => x.Variants).Where(x => x.CompanyId == s.CompanyId); if (s.CategoryId is Guid c) q = q.Where(x => x.CategoryId == c); if (s.BrandId is Guid b) q = q.Where(x => x.BrandId == b); if (s.IsActive is bool a) q = q.Where(x => x.IsActive == a); if (s.TracksInventory is bool t) q = q.Where(x => x.TracksInventory == t); if (!string.IsNullOrWhiteSpace(s.Text)) { var text = s.Text.ToLower(); q = q.Where(x => x.Name.ToLower().Contains(text) || x.Variants.Any(v => v.Sku.ToLower().Contains(text) || (v.Barcode != null && v.Barcode.Contains(text)))); } q = s.Sort == "createdAt" ? q.OrderByDescending(x => x.CreatedAt) : q.OrderBy(x => x.Name); var products = await q.Skip((Math.Max(1, s.Page) - 1) * Math.Clamp(s.PageSize, 1, 100)).Take(Math.Clamp(s.PageSize, 1, 100)).ToListAsync(ct); var ids = products.Select(x => x.Id).ToList(); var images = await db.ProductImages.AsNoTracking().Where(x => ids.Contains(x.ProductId)).OrderBy(x => x.SortOrder).ToListAsync(ct); return products.Select(x => Map(x, images.Where(i => i.ProductId == x.Id).Select(i => i.Url).ToList())).ToList(); }
    public async Task<Result<ProductResponse>> UpdateProductAsync(Guid id, UpdateProductRequest r, CancellationToken ct) { var product = await db.Products.Include(x => x.Variants).SingleOrDefaultAsync(x => x.Id == id && x.CompanyId == context.CompanyId, ct); if (product is null) return Result<ProductResponse>.Failure(new("catalog.product_not_found", "Product was not found.")); if (!await db.Categories.AnyAsync(x => x.Id == r.CategoryId && x.CompanyId == product.CompanyId, ct)) return Result<ProductResponse>.Failure(new("catalog.category_invalid", "Category is invalid.")); var result = product.Update(r.CategoryId, r.BrandId, r.Name, r.Description, r.ProductType, r.TracksInventory, Now); if (result.IsFailure) return Result<ProductResponse>.Failure(result.Error); await db.SaveChangesAsync(ct); var images = await db.ProductImages.AsNoTracking().Where(x => x.ProductId == id).OrderBy(x => x.SortOrder).Select(x => x.Url).ToListAsync(ct); return Result<ProductResponse>.Success(Map(product, images)); }
    public async Task<Result<ProductVariantResponse>> UpdateVariantAsync(Guid id, UpdateProductVariantRequest r, CancellationToken ct) { var variant = await db.ProductVariants.SingleOrDefaultAsync(x => x.Id == id && x.CompanyId == context.CompanyId, ct); if (variant is null) return Result<ProductVariantResponse>.Failure(new("catalog.variant_not_found", "Variant was not found.")); var sku = r.Sku.Trim().ToUpperInvariant(); if (await db.ProductVariants.AnyAsync(x => x.Id != id && x.CompanyId == variant.CompanyId && x.Sku == sku, ct)) return Result<ProductVariantResponse>.Failure(new("catalog.sku_conflict", "SKU must be unique per company.")); var result = variant.Update(r.Sku, r.Barcode, r.Name, r.UnitOfMeasure, r.Cost, r.SalePrice, r.TaxRate, Now); if (result.IsFailure) return Result<ProductVariantResponse>.Failure(result.Error); await db.SaveChangesAsync(ct); return Result<ProductVariantResponse>.Success(Map(variant)); }
    public async Task<Result<string>> AddProductImageAsync(Guid productId, string extension, byte[] content, CancellationToken ct) { var product = await db.Products.SingleOrDefaultAsync(x => x.Id == productId && x.CompanyId == context.CompanyId, ct); if (product is null) return Result<string>.Failure(new("catalog.product_not_found", "Product was not found.")); if (content.Length is 0 or > 5_000_000) return Result<string>.Failure(new("catalog.image_size_invalid", "Image must be between 1 byte and 5 MB.")); var allowed = new[] { ".jpg", ".jpeg", ".png", ".webp" }; extension = extension.ToLowerInvariant(); if (!allowed.Contains(extension)) return Result<string>.Failure(new("catalog.image_type_invalid", "Use JPG, PNG or WEBP images.")); var fileName = $"{Guid.NewGuid():N}{extension}"; var relativeUrl = $"/uploads/products/{fileName}"; var directory = Path.Combine(environment.ContentRootPath, "wwwroot", "uploads", "products"); Directory.CreateDirectory(directory); await File.WriteAllBytesAsync(Path.Combine(directory, fileName), content, ct); var sortOrder = await db.ProductImages.CountAsync(x => x.ProductId == productId, ct); db.ProductImages.Add(new ProductImage(productId, relativeUrl, sortOrder)); await db.SaveChangesAsync(ct); return Result<string>.Success(relativeUrl); }
    public async Task<bool> UpdatePricingAsync(Guid variantId, decimal cost, decimal? salePrice, CancellationToken ct) { var variant = await db.ProductVariants.SingleOrDefaultAsync(x => x.Id == variantId, ct); if (variant is null) return false; var result = variant.Update(variant.Sku, variant.Barcode, variant.Name, variant.UnitOfMeasure, cost, salePrice ?? variant.BasePrice, variant.TaxRate, Now); if (result.IsFailure) return false; await db.SaveChangesAsync(ct); return true; }
    public async Task<Result> SetProductActiveAsync(Guid id, bool active, CancellationToken ct) { var x = await db.Products.SingleOrDefaultAsync(x => x.Id == id && x.CompanyId == context.CompanyId, ct); if (x is null) return Result.Failure(new("catalog.product_not_found", "Product was not found.")); x.SetActive(active, Now); await db.SaveChangesAsync(ct); return Result.Success(); }
    public async Task<Result> SetVariantActiveAsync(Guid id, bool active, CancellationToken ct) { var x = await db.ProductVariants.SingleOrDefaultAsync(x => x.Id == id && x.CompanyId == context.CompanyId, ct); if (x is null) return Result.Failure(new("catalog.variant_not_found", "Variant was not found.")); x.SetActive(active, Now); await db.SaveChangesAsync(ct); return Result.Success(); }
    private async Task SaveAttributes(Guid variantId, Guid companyId, IReadOnlyDictionary<string, string>? attributes, CancellationToken ct) { if (attributes is null) return; foreach (var pair in attributes) { var name = pair.Key.Trim(); var value = pair.Value.Trim(); var definition = await db.AttributeDefinitions.SingleOrDefaultAsync(x => x.CompanyId == companyId && x.Name == name, ct) ?? new AttributeDefinition(companyId, name); if (definition.Id == Guid.Empty) throw new InvalidOperationException(); if (db.Entry(definition).State == EntityState.Detached) db.AttributeDefinitions.Add(definition); var attributeValue = await db.AttributeValues.SingleOrDefaultAsync(x => x.AttributeDefinitionId == definition.Id && x.Value == value, ct) ?? new AttributeValue(definition.Id, value); if (db.Entry(attributeValue).State == EntityState.Detached) db.AttributeValues.Add(attributeValue); db.ProductVariantAttributes.Add(new() { ProductVariantId = variantId, AttributeValueId = attributeValue.Id }); } }
    private bool Allowed(Guid companyId) => context.CompanyId == companyId;
    private static Result<T> Denied<T>() => Result<T>.Failure(new("catalog.company_context_invalid", "Requested company does not match the current company context."));
    private static ProductResponse Map(Product x, IReadOnlyCollection<string> images) => new(x.Id, x.CompanyId, x.CategoryId, x.BrandId, x.Name, x.Description, x.ProductType, x.TracksInventory, x.IsActive, images, x.Variants.Select(Map).ToList());
    private static ProductVariantResponse Map(ProductVariant v) => new(v.Id, v.Sku, v.Barcode, v.Name, v.UnitOfMeasure, v.Cost, v.BasePrice, v.TaxRate, v.IsActive, new Dictionary<string, string>());
}
internal sealed class ProductVariantInventoryView(CatalogDbContext db) : IProductVariantInventoryView { public Task<ProductVariantInventoryInfo?> GetAsync(Guid id, CancellationToken ct) => (from v in db.ProductVariants.AsNoTracking() join p in db.Products on v.ProductId equals p.Id where v.Id == id select new ProductVariantInventoryInfo(v.Id, v.CompanyId, p.IsActive, v.IsActive, p.TracksInventory)).SingleOrDefaultAsync(ct); }
internal sealed class ProductCatalogView(CatalogDbContext db) : IProductCatalogView { public async Task<IReadOnlyList<ProductVariantLookup>> GetVariantsAsync(Guid companyId, CancellationToken ct) { var rows = await (from v in db.ProductVariants.AsNoTracking() join p in db.Products.AsNoTracking() on v.ProductId equals p.Id where v.CompanyId == companyId orderby p.Name, v.Name select new { v.Id, ProductId = p.Id, ProductName = p.Name, VariantName = v.Name, v.Sku, v.Barcode, v.UnitOfMeasure, v.Cost, SalePrice = v.BasePrice, p.TracksInventory, ProductActive = p.IsActive, VariantActive = v.IsActive }).ToListAsync(ct); return rows.Select(x => new ProductVariantLookup(x.Id, x.ProductId, x.ProductName, x.VariantName, x.Sku, x.Barcode, x.UnitOfMeasure, x.Cost, x.SalePrice, x.TracksInventory, x.ProductActive && x.VariantActive)).ToList(); } }
public static class CatalogModule { public static IServiceCollection AddCatalogModule(this IServiceCollection s, IConfiguration c) { s.AddDbContext<CatalogDbContext>(o => o.UseNpgsql(c.GetConnectionString("Database"))); s.AddScoped<CatalogService>(); s.AddScoped<ICatalogService>(sp => sp.GetRequiredService<CatalogService>()); s.AddScoped<IProductVariantPricing>(sp => sp.GetRequiredService<CatalogService>()); s.AddScoped<IProductVariantInventoryView, ProductVariantInventoryView>(); s.AddScoped<IProductCatalogView, ProductCatalogView>(); return s; } }
